import json
from pathlib import Path
p=Path(__file__).resolve().parent
out=p/'public';out.mkdir(exist_ok=True)
base=json.loads((p.parent/'validation057/public/rows.json').read_text(encoding='utf8'))
reasons={'review_structure_unresolved':'结构证据尚未解决','review_DIS_vs_weak_order':'DIS / 弱有序待区分','review_above_DIS_energy':'自由能高于 DIS 复核带','review_invalid_density':'密度质量异常'}
rows=[]
for b in base:
 r=json.loads((p/'replay_results'/f"{b['id']}.json").read_text(encoding='utf8'))
 if not r['status'].startswith('review_'):continue
 e=r['joint_evidence']
 rows.append(dict(id=b['id'],run_id=b['run_id'],initial_seed=b['initial_seed'],fa=b['fa'],chi_n=b['chi_n'],reason=reasons[r['status']],status=r['status'],image='../validation057/'+b.get('density_view',f"images/{b['id']}.png"),cell=b['review'].get('cell'),input_hashes=b['review']['input_hashes'],amplitude=e['amplitude'],energy=e['energy'],convergence=e['convergence'],machine=r.get('morphology_candidate'),machine_status=r.get('morphology_status')))
assert len(rows)==232
(out/'rows.json').write_text(json.dumps(rows,ensure_ascii=False),encoding='utf8')
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>联合判定待复核 · SCFT</title>
<style>*{box-sizing:border-box}body{font:16px/1.6 system-ui;background:#f3f6fa;color:#192c3c;margin:24px}header,article{background:white;border:1px solid #dae2ec;border-radius:12px;padding:20px}nav{display:flex;gap:18px;flex-wrap:wrap}a{color:#145e96}#cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,430px),1fr));gap:18px;margin-top:20px}img{width:100%;height:auto}button,select,input,textarea{font:inherit;padding:8px;border:1px solid #bac8d8;border-radius:6px;margin:4px 0}textarea{width:100%}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:6px;border-bottom:1px solid #e4eaf1;text-align:left;overflow-wrap:anywhere}.reason{background:#fff3da;padding:10px;border-radius:6px}.muted{color:#586b7d;font-size:14px}summary{cursor:pointer;margin:10px 0}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center}h2{margin:0}#notice{color:#a22525}</style>
<header><nav><a href="/">工作台</a><a href="../phases.html">相态图鉴</a><a href="../validation057/">完整1356例</a><a href="../review.html">原20例复核</a><a href="/database/">数据库</a></nav><h1>振幅 × 自由能 × 收敛：待复核任务</h1><p>060 实验副本筛出 232 例：结构未解决 215 例，DIS / 弱有序 14 例，自由能异常 2 例，密度质量异常 1 例。</p><p class="muted">保留初始种子，机器相名默认隐藏。人工记录与同一浏览器、同一地址下的057页面共用；请导出保存，不会回填数据库。复核队列不是全部潜在错误的清单，7272 等已知形貌问题仍须另行核查。</p><div class="toolbar"><select id="reason"><option value="">全部原因</option></select><select id="seed"><option value="">全部初始相</option><option>LAM</option><option>HEX</option></select><input id="search" placeholder="搜索编号，如 8410"><select id="done"><option value="">全部记录</option><option value="no">尚未填写相名</option><option value="yes">已填写相名</option></select><button id="prev">上一页</button><span id="page"></span><button id="next">下一页</button><button id="export">导出本队列人工记录</button></div><p id="notice" role="status"></p></header><main id="cards"></main>
<script>
const $=id=>document.getElementById(id),key='validation057-human-v1';let rows=[],page=0;
const read=()=>{try{return JSON.parse(localStorage.getItem(key)||'{}')}catch(e){$('notice').textContent='无法读取已有记录，请先备份浏览器数据。';throw e}};
function put(id,patch){try{let s=read();s[id]={...s[id],...patch};localStorage.setItem(key,JSON.stringify(s));$('notice').textContent='已保存在当前浏览器；请导出备份。'}catch(e){$('notice').textContent='保存失败，请勿关闭页面，复制当前记录后重试。'}}
const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>typeof x==='number'?Number(x).toPrecision(7):'—';
function render(){const store=read();let a=rows.filter(r=>(!$('reason').value||r.status==$('reason').value)&&(!$('seed').value||r.initial_seed==$('seed').value)&&String(r.run_id).includes($('search').value.trim())&&(!$('done').value||Boolean(store[r.id]?.label)==($('done').value==='yes')));page=Math.min(page,Math.max(0,Math.ceil(a.length/12)-1));$('page').textContent=`${page+1} / ${Math.max(1,Math.ceil(a.length/12))} · ${a.length} 例`;$('prev').disabled=page===0;$('next').disabled=(page+1)*12>=a.length;$('cards').replaceChildren();
for(const r of a.slice(page*12,page*12+12)){const d=store[r.id]||{},e=r.energy,c=r.convergence,s=document.createElement('article');s.innerHTML=`<h2>${esc(r.id)}</h2><p>初始种子：${esc(r.initial_seed)} · fA=${esc(r.fa)} · χN=${esc(r.chi_n)}</p><p class="reason">${esc(r.reason)}</p><a href="${esc(r.image)}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(r.image)}" alt="${esc(r.id)}真实密度图（点击放大）"></a><table><thead><tr><th>组分</th><th>最小 / 最大</th><th>极差 / 标准差</th></tr></thead><tbody>${r.amplitude.map((v,i)=>`<tr><td>φ${i?'B':'A'}</td><td>${fmt(v.min)} / ${fmt(v.max)}</td><td>${fmt(v.ptp)} / ${fmt(v.std)}</td></tr>`).join('')}</tbody></table><table><tr><th>自由能 F</th><td>${fmt(e.F)}</td></tr><tr><th>DIS 基线</th><td>${fmt(e.baseline?.value)}</td></tr><tr><th>ΔF = F − FDIS</th><td>${fmt(e.delta_F)}</td></tr><tr><th>收敛核验</th><td>${c.passed?'通过':'未通过或无法核实'}</td></tr><tr><th>残差 / 阈值</th><td>${fmt(c.residual)} / ${fmt(c.residual_tolerance)}</td></tr><tr><th>应力 / 阈值</th><td>${fmt(c.stress_norm)} / ${fmt(c.stress_tolerance)}</td></tr></table><details><summary>晶胞参数与判定说明</summary><p>边长：${(r.cell?.lengths||[]).map(fmt).join(' / ')}<br>边长比：${(r.cell?.ratios||[]).map(fmt).join(' / ')}</p><p>夹角矩阵（°）：${(r.cell?.angle_matrix_degrees||[]).map(v=>v.map(fmt).join(' / ')).join('<br>')}</p><p class="muted">弱幅复核带：极差 ≤ 0.01 且标准差 ≤ 0.003；自由能复核容差 1e-6。这些是实验复核阈值，不是相变边界。低于 DIS 不代表全局稳定。</p></details><details class="machine"><summary>显示机器形貌候选</summary><p>原形貌候选：${esc(r.machine||'未定')}。联合判定：待复核。</p></details><label>人工相名 <select class="label"><option value="">未确认</option>${['LAM','HEX','DIS','C3','FCC','BCC','SC','SPC','PtS','PL','HPL','unseen'].map(x=>`<option>${x}</option>`).join('')}</select></label><textarea aria-label="人工观察" placeholder="人工观察及疑问"></textarea>`;
const select=s.querySelector('.label'),notes=s.querySelector('textarea');if(d.label&&!Array.from(select.options).some(o=>o.value===d.label))select.add(new Option(d.label,d.label));select.value=d.label||'';notes.value=d.notes||'';const save=()=>put(r.id,{label:select.value,notes:notes.value,input_hashes:r.input_hashes,reviewer_kind:'human',updated_at:new Date().toISOString()});select.onchange=save;notes.oninput=save;s.querySelector('.machine').ontoggle=ev=>{if(ev.target.open)put(r.id,{machine_revealed:true})};$('cards').append(s)}}
for(const id of ['reason','seed','search','done'])$(id).oninput=()=>{page=0;render()};$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};window.addEventListener('storage',e=>{if(e.key===key)render()});$('export').onclick=()=>{const s=read(),reviews=Object.fromEntries(rows.filter(r=>s[r.id]).map(r=>[r.id,s[r.id]]));const url=URL.createObjectURL(new Blob([JSON.stringify({batch:'060-review',reviews},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='validation060-human.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
fetch('rows.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(x=>{rows=x;for(const [v,label] of new Map(rows.map(r=>[r.status,r.reason])))$('reason').add(new Option(label,v));render()}).catch(e=>{$('notice').textContent='加载失败，请刷新重试：'+e.message});
</script></html>'''
(out/'index.html').write_text(html,encoding='utf8')
print('Published local static page:',len(rows))
